from itertools import permutations
fits = set()
for seat in permutations("PQRST"):
    at = {p: i for i, p in enumerate(seat)}
    if at["Q"] not in (0, 4):
        continue
    if abs(at["R"] - at["Q"]) != 1:
        continue
    if at["S"] != 2:
        continue
    if abs(at["P"] - at["S"]) == 1:
        continue
    fits.add(seat[4] if at["Q"] == 0 else seat[0])
print(sorted(fits)[0] if len(fits) == 1 else f"not unique: {sorted(fits)}")

from itertools import product
labels = ["cat", "animal", "pet"]
models = []
for combo in product([False, True], repeat=12):
    cre = [dict(zip(labels, combo[i * 3:i * 3 + 3])) for i in range(4)]
    if not any(c["cat"] for c in cre):
        continue
    if not any(c["pet"] for c in cre):
        continue
    if any(not c["animal"] for c in cre if c["cat"]):
        continue
    if not any(c["animal"] and c["pet"] for c in cre):
        continue
    models.append(cre)
tests = {
    "Some pets are animals": lambda m: any(c["pet"] and c["animal"] for c in m),
    "Some cats are pets": lambda m: any(c["cat"] and c["pet"] for c in m),
    "All pets are animals": lambda m: all(c["animal"] for c in m if c["pet"]),
    "No cat is a pet": lambda m: not any(c["cat"] and c["pet"] for c in m),
}
good = [k for k, f in tests.items() if all(f(m) for m in models)]
print(good[0] if len(good) == 1 else f"not unique: {good}")
